<?php
require_once __DIR__ . '/../includes/admin_only.php'; require __DIR__ . '/../includes/db.php'; require_once __DIR__ . '/../includes/rental_status.php'; sync_rental_and_car_status($conn);
$from=$_GET['from_date']??date('Y-m-01'); $to=$_GET['to_date']??date('Y-m-d');
$summary=$conn->query("SELECT COUNT(*) rentals, IFNULL(SUM(total_cost),0) revenue FROM rentals WHERE status<>'Deleted' AND start_date BETWEEN '".$conn->real_escape_string($from)."' AND '".$conn->real_escape_string($to)."'")->fetch_assoc();
$payments=$conn->query("SELECT IFNULL(SUM(amount),0) paid FROM payment WHERE payment_date BETWEEN '".$conn->real_escape_string($from)."' AND '".$conn->real_escape_string($to)."'")->fetch_assoc();
$expenses=$conn->query("SELECT IFNULL(SUM(amount),0) total_expense FROM expenses WHERE expense_date BETWEEN '".$conn->real_escape_string($from)."' AND '".$conn->real_escape_string($to)."'")->fetch_assoc();
$util=$conn->query("SELECT ca.reg_no,m.name AS make_name,mo.name AS model_name,y.year AS car_year,COUNT(r.id) rental_count,IFNULL(SUM(r.total_cost),0) revenue FROM cars ca LEFT JOIN rentals r ON r.cars_id=ca.id AND r.status<>'Deleted' AND r.start_date BETWEEN '".$conn->real_escape_string($from)."' AND '".$conn->real_escape_string($to)."' LEFT JOIN makes m ON ca.make_id=m.id LEFT JOIN models mo ON ca.model_id=mo.id LEFT JOIN car_years y ON ca.year_id=y.id GROUP BY ca.id,ca.reg_no,m.name,mo.name,y.year ORDER BY rental_count DESC,revenue DESC");
$incidents=$conn->query("SELECT ca.reg_no,COUNT(d.id) damage_count,IFNULL(SUM(COALESCE(d.repair_cost,d.estimated_cost,0)),0) damage_cost FROM car_damages d JOIN cars ca ON d.car_id=ca.id WHERE d.date_reported BETWEEN '".$conn->real_escape_string($from)."' AND '".$conn->real_escape_string($to)."' GROUP BY ca.id,ca.reg_no ORDER BY damage_count DESC");
?>
<!DOCTYPE html><html><head><title>Analytics</title></head><body><?php include __DIR__.'/../includes/header.php'; include __DIR__.'/../includes/leftsidebar.php';?><div class="content-page"><h2>Reporting & Analytics</h2><form method="GET" class="filter-box"><div><label>From</label><input type="date" name="from_date" value="<?=h($from)?>"></div><div><label>To</label><input type="date" name="to_date" value="<?=h($to)?>"></div><button>Apply</button></form><div class="row"><div class="card-box"><p>Rentals</p><h2><?=h($summary['rentals'])?></h2></div><div class="card-box"><p>Rental Revenue</p><h2><?=money((float)$summary['revenue'])?></h2></div><div class="card-box"><p>Payments Collected</p><h2><?=money((float)$payments['paid'])?></h2></div><div class="card-box"><p>Expenses</p><h2><?=money((float)$expenses['total_expense'])?></h2></div><div class="card-box"><p>Estimated Profit</p><h2><?=money((float)$payments['paid']-(float)$expenses['total_expense'])?></h2></div></div><h3>Vehicle Utilization & Profitability</h3><table class="table" border="1" cellpadding="10"><tr><th>Car</th><th>Rental Count</th><th>Revenue</th></tr><?php if($util&&$util->num_rows):while($u=$util->fetch_assoc()):?><tr><td><?=h(car_display_name($u))?></td><td><?=h($u['rental_count'])?></td><td><?=money((float)$u['revenue'])?></td></tr><?php endwhile;endif;?></table><h3>Late Returns & Damage Incidents</h3><table class="table" border="1" cellpadding="10"><tr><th>Car</th><th>Damage Count</th><th>Damage Cost</th></tr><?php if($incidents&&$incidents->num_rows):while($i=$incidents->fetch_assoc()):?><tr><td><?=h($i['reg_no'])?></td><td><?=h($i['damage_count'])?></td><td><?=money((float)$i['damage_cost'])?></td></tr><?php endwhile;else:?><tr><td colspan="3">No damage incidents in this period.</td></tr><?php endif;?></table></div></body></html>
